import type { GeospatialCamera } from "@babylonjs/lite";

/**
 * Convert a latitude/longitude (in degrees) to a point on the planet's
 * surface — a sphere of radius `radius` centred at the origin.
 *
 * Coordinate convention (see camera notes #54):
 *   +X is the centre at latitude 0 / longitude 0,
 *   +Z is north,
 *   -Y is east (yaw PI/2, i.e. "east", looks toward -Y).
 */
function latLonToSurface(radius: number, latitudeDeg: number, longitudeDeg: number): { x: number; y: number; z: number } {
  const phi = (latitudeDeg * Math.PI) / 180;
  const lambda = (longitudeDeg * Math.PI) / 180;
  const cosPhi = Math.cos(phi);
  return {
    x: radius * cosPhi * Math.cos(lambda),
    y: -radius * cosPhi * Math.sin(lambda),
    z: radius * Math.sin(phi),
  };
}

export function centerOnLatLon(camera: GeospatialCamera, latitudeDeg: number, longitudeDeg: number): void {
  const radius = camera.limits.planetRadius;
  // Assign a whole new object to `center` so the camera re-orbits around the
  // new centre immediately (writing center.x/y/z in place would not, see
  // camera notes #11). yaw, pitch and radius are left untouched, so the
  // heading, tilt and zoom stay as they were.
  camera.center = latLonToSurface(radius, latitudeDeg, longitudeDeg);
}
```

